const $=id=>document.getElementById(id);
const patients={alex:{name:'Alex Morgan',age:16,seed:0},jordan:{name:'Jordan Lee',age:14,seed:3},sam:{name:'Sam Rivera',age:17,seed:7}};
let current='alex',period=30;
function dataset(key){const s=patients[key].seed;return Array.from({length:30},(_,i)=>{const date=new Date(Date.UTC(2026,4,26+i)).toISOString().slice(0,10),missing=(i+s)%11===3;const symptomatic=!missing&&((i+s)%5===0||(i>19&&(i+s)%3===0));const symptoms=symptomatic?[(i+s)%2?'Coughing':'Wheezing',...(i%3===0?['Shortness of breath']:[]),...(i%5===0?['Chest tightness']:[])]:[];const quality=i%8===4?'conflicting':i%6===2?'rejected':'accepted';return {date,missing,symptoms,zone:missing?'unknown':symptomatic?'yellow':'green',doses:missing?0:(i+s)%6===0?1:2,fev:missing?null:+(2.68+s*.035-Math.max(0,i-17)*.018+Math.sin(i*1.4+s)*.11).toFixed(2),quality,submissions:missing?0:i%7===0?3:1,rescue:symptomatic?1:0,school:symptomatic&&i%5===0?1:0,feeling:symptomatic?(i%2?'Okay':'Great'):'Great'};});}
const rows=()=>dataset(current).slice(-period),fmt=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
function modal(html){$('detail-content').innerHTML=html;$('detail').showModal();}
document.querySelector('.close').onclick=()=>$('detail').close();$('detail').addEventListener('click',e=>{if(e.target===$('detail'))$('detail').close()});
function detail(date){const d=dataset(current).find(x=>x.date===date);modal(`<div class="eyebrow">DAILY REVIEW · FICTIONAL DATA</div><h2>${fmt(date)}, 2026</h2>${d.missing?'<p>No tracker submission or dose report was recorded. Symptoms, medication use, and plan zone are unknown.</p>':`<p>${d.submissions} tracker submission${d.submissions>1?'s':''} grouped into this day. Symptoms are the union of reported symptoms; zone uses the most concerning recorded status.</p><div class="detail-grid"><div>Reported symptoms<strong>${d.symptoms.join(', ')||'None reported'}</strong></div><div>Latest wellbeing<strong>${d.feeling}</strong></div><div>Best device reading<strong>${d.fev.toFixed(2)} L FEV1</strong></div><div>Device quality<strong>${d.quality==='conflicting'?'Conflicting flags':d.quality}</strong></div><div>Controller reported<strong>${d.doses} / 2 scheduled doses</strong></div><div>Rescue reports<strong>${d.rescue}</strong></div></div><p>${d.quality==='accepted'?'This accepted reading is included in the trend.':'This reading is excluded from the trend because its quality is rejected or unresolved.'} Medication use is self-reported. ${d.school?'One school day was reported missed.':''}</p>${d.submissions>1?'<p><strong>Repeated-entry example:</strong> 08:10 symptom check, 08:16 spirometry step, 18:45 wellbeing check. These are illustrative records, not separate tracked days.</p>':''}`}`);}
function render(){const p=patients[current],r=rows(),logged=r.filter(d=>!d.missing),sym=logged.filter(d=>d.symptoms.length),accepted=r.filter(d=>d.fev!==null&&d.quality==='accepted'),doses=r.reduce((s,d)=>s+d.doses,0),expected=r.length*2,pc=Math.round(doses/expected*100),school=r.reduce((s,d)=>s+d.school,0),last=accepted.at(-1);$('patient-name').innerHTML=`${p.name} <span class="tag">Demo patient</span>`;$('patient-meta').textContent=`${p.age} years · Asthma tracker · Enrolled May 2026`;$('crumb').textContent=p.name;$('initials').textContent=p.name.split(' ').map(x=>x[0]).join('');$('date-label').textContent=`${fmt(r[0].date)} – ${fmt(r.at(-1).date)}, 2026 · ${r.length} days`;
const first=accepted[0],delta=last&&first?last.fev-first.fev:0;$('summary-title').textContent=`${sym.length} days with symptoms. ${pc}% of scheduled doses reported.`;$('summary-text').textContent=`${logged.length} of ${r.length} days have tracker entries. ${accepted.length} quality-accepted lung-function readings${first&&last?`; latest ${last.fev.toFixed(2)} L, ${Math.abs(delta).toFixed(2)} L ${delta<0?'below':'above'} the first accepted reading in this period`:''}. Review symptoms alongside medication reporting and missing data.`;
const metrics=[['Symptom days',sym.length,`/ ${logged.length} logged days`,'Denominator excludes days without entries'],['Controller reporting',pc+'%','',`${doses} of ${expected} scheduled doses reported`],['Latest accepted FEV1',last?last.fev.toFixed(2):'—','L',last?`${fmt(last.date)} · ${accepted.length} accepted readings`:'No accepted readings in period'],['School days missed',school,'days','Patient reported · missing days unknown']];$('metrics').innerHTML=metrics.map(([label,value,unit,note])=>`<section class="metric"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value">${value}<small>${unit}</small></div><div class="metric-note">${note}</div></section>`).join('');
const x=i=>40+i/(r.length-1)*500,y=v=>185-(v-1.8)/1.6*150;const pts=accepted.map(d=>[x(r.indexOf(d)),y(d.fev),d]);$('lung-chart').innerHTML=`<svg viewBox="0 0 565 220" role="img" aria-label="Accepted FEV1 measurements in liters over the selected period"><title>FEV1 trend for ${p.name}</title>${[2,2.4,2.8,3.2].map(v=>`<line x1="40" y1="${y(v)}" x2="545" y2="${y(v)}" stroke="#edf0ec"/><text x="5" y="${y(v)+4}">${v.toFixed(1)}</text>`).join('')}<polyline points="${pts.map(a=>a.slice(0,2).join(',')).join(' ')}" fill="none" stroke="#3f8d80" stroke-width="2.5"/>${pts.map(([a,b,d])=>`<circle tabindex="0" role="button" aria-label="${fmt(d.date)}, FEV1 ${d.fev} liters. Open daily details" data-date="${d.date}" cx="${a}" cy="${b}" r="4" fill="white" stroke="#3f8d80" stroke-width="2"><title>${fmt(d.date)} · ${d.fev} L</title></circle>`).join('')}${[0,Math.floor(r.length/2),r.length-1].map(i=>`<text x="${x(i)}" y="212" text-anchor="${i===0?'start':i===r.length-1?'end':'middle'}">${fmt(r[i].date)}</text>`).join('')}</svg>`;
$('symptoms').innerHTML=['Coughing','Wheezing','Shortness of breath','Chest tightness'].map(s=>{const n=r.filter(d=>d.symptoms.includes(s)).length;return `<div class="symptom-row"><div><span>${s}</span><span>${n} days</span></div><div class="bar"><span style="width:${n/logged.length*100}%"></span></div></div>`}).join('');$('medication').innerHTML=`<div class="med-heading"><span>Demo controller A<br><small style="color:var(--muted)">Morning + evening · 2 doses/day</small></span><strong>${pc}<small style="font-size:12px">%</small></strong></div><div class="dose-bar"><span style="width:${pc}%"></span><span style="width:${100-pc}%"></span></div><div class="dose-legend"><span><i class="legend teal-bg"></i>${doses} reported</span><span><i class="legend gray-bg"></i>${expected-doses} unreported</span></div>`;
const specialty=$('specialty').value;const prompts=specialty==='Nursing'?['Explore whether reminders and dose logging fit the daily routine.','Review missing entries and spirometry technique with the family.','Confirm the current medication schedule and action plan.']:specialty==='Primary care'?['Ask how symptoms are affecting school and everyday activities.','Discuss barriers to reporting or taking scheduled medication.','Review changes with the patient and their specialty care team.']:['Review symptom days alongside accepted lung-function readings.','Explore whether unreported doses reflect missed treatment or logging gaps.','Check device technique and clarify conflicting quality reports.'];$('prompts').innerHTML=prompts.map((s,i)=>`<div class="prompt"><span>0${i+1}</span><div>${s}</div></div>`).join('');
$('timeline').style.gridTemplateColumns=`repeat(${r.length},minmax(18px,1fr))`;$('timeline').innerHTML=r.map(d=>`<button class="day ${d.zone}" data-date="${d.date}" aria-label="${fmt(d.date)}: ${d.zone==='unknown'?'no entry':d.zone+' zone'}. Review day"><i></i>${+d.date.slice(-2)}</button>`).join('');
const excluded=r.filter(d=>d.fev!==null&&d.quality!=='accepted').length;$('quality-title').textContent=`Data coverage & interpretation · ${r.length-logged.length} days without entries · ${excluded} device readings excluded`;$('quality-content').innerHTML=`<p><strong>Daily aggregation:</strong> repeated submissions count as one tracked day. Symptoms use the union of answers; wellbeing uses the latest answer; zone uses the most concerning recorded status. Spirometry uses the daily best accepted FEV1. Lines connect available readings across gaps and do not imply measurements on missing days.</p><p><strong>Quality:</strong> ${excluded} rejected or conflicting readings are excluded from the chart but remain in daily details. No quality flag is silently resolved. Values are shown to two decimal places with units.</p><p><strong>Medication:</strong> ${doses}/${expected} scheduled doses were reported. The denominator assumes an unchanged twice-daily schedule throughout this fictional period. Missing reports do not establish missed doses. Rescue medication is not included in this percentage.</p><p><strong>Scope:</strong> All records are generated examples, anchored to June 24, 2026. The summary is computed from displayed records, not AI clinical advice. No live monitoring or medical-record integration.</p>`;
$('log-body').innerHTML=[...r].reverse().map(d=>`<tr><td><button data-date="${d.date}">${fmt(d.date)}</button></td><td>${d.missing?'No entry':d.symptoms.join(', ')||'None reported'}</td><td>${d.fev===null?'—':d.fev.toFixed(2)+' L'}${d.fev!==null&&d.quality!=='accepted'?'<br><small>Excluded: '+d.quality+'</small>':''}</td><td>${d.doses}/2 reported</td><td>${d.zone==='unknown'?'Unknown':d.zone}</td><td>${d.submissions}</td></tr>`).join('');
document.querySelectorAll('[data-date]').forEach(el=>{el.onclick=()=>detail(el.dataset.date);if(el.tagName.toLowerCase()==='circle')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(el.dataset.date)}}});}
$('patient').onchange=e=>{current=e.target.value;render()};$('range').onchange=e=>{period=+e.target.value;render()};$('specialty').onchange=render;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('selected',x===b));['overview','logs','plan'].forEach(id=>$(id).classList.toggle('hidden',id!==b.dataset.tab))});
$('patient-mode').onclick=()=>{const r=rows(),logged=r.filter(d=>!d.missing),n=logged.filter(d=>d.symptoms.length).length;modal(`<div class="eyebrow">LET’S LOOK TOGETHER</div><h2>Your last ${period} days at home</h2><p>You checked in on <strong>${logged.length} days</strong>. You reported symptoms on <strong>${n} of those days</strong>.</p><p>There are ${period-logged.length} days without check-ins, so we don't know how those days went.</p><h3>What was going on for you?</h3><p>Which days felt hardest? How did taking and recording your medication fit into your routine? What would make tracking easier?</p><p>These are fictional examples for a design demonstration.</p>`)};
$('about').onclick=()=>modal('<div class="eyebrow">ABOUT THIS VIEW</div><h2>Home data, ready for a conversation.</h2><p>A SMART@Home clinician-view design based on the supplied hackathon brief. All patients, medications, readings, and schedules are fictional.</p><p>Interactive date ranges, specialty prompts, patient switching, daily reviews, patient discussion mode, and CSV export work locally. This is not a clinical system and has no Epic integration.</p>');
$('export').onclick=()=>{const header=['date','patient','tracker_entries','symptoms','fev1_liters','device_quality','reported_controller_doses','scheduled_controller_doses','recorded_zone','rescue_reports','school_days_missed'];const csv=[header,...rows().map(d=>[d.date,patients[current].name,d.submissions,d.missing?'unknown':d.symptoms.join('; ')||'none reported',d.fev??'',d.fev===null?'no reading':d.quality,d.doses,2,d.zone,d.missing?'':d.rescue,d.missing?'':d.school])].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`smart-home-fictional-${current}-${period}days.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));const page=b.dataset.page;$('patient-page').classList.toggle('hidden',page!=='patients');$('catalog-page').classList.toggle('hidden',page==='patients');if(page==='patients'){$('crumb').textContent=patients[current].name;return}$('crumb').textContent=page==='trackers'?'Trackers':'Studies';$('catalog-page').innerHTML=page==='trackers'?'<div class="catalog-title"><div class="eyebrow">CONFIGURATION OVERVIEW</div><h1>Trackers</h1><p>One framework. Different questions for each condition.</p></div><div class="catalog-list"><article class="card"><span class="pill teal">Demo available</span><h2 style="margin-top:20px">Asthma</h2><p>Symptoms, controller and rescue use, lung function, school absence, and recorded action-plan zones.</p><button class="button" id="open-asthma">Open patient view ↗</button></article><article class="card"><span class="pill">Future configuration</span><h2 style="margin-top:20px">Migraine</h2><p>Headache frequency, severity, medication reporting, triggers, and impact on daily activities. No example records configured.</p></article><article class="card"><span class="pill">Future configuration</span><h2 style="margin-top:20px">IBD</h2><p>Condition-specific symptoms, medication reporting, wellbeing, and daily functioning. No example records configured.</p></article></div>':'<div class="catalog-title"><div class="eyebrow">RESEARCH CONTEXT</div><h1>Studies</h1><p>No study management is connected to this prototype.</p></div><article class="card"><h2>Asthma pilot context</h2><p>The supplied brief describes an adolescent asthma pilot at Cincinnati Children’s. This dashboard demonstrates an individual-patient view; it does not display enrollment, study outcomes, or real participant data.</p><p>Study identifier cited in the brief: NCT06159127. Current study status has not been verified.</p></article>';if($('open-asthma'))$('open-asthma').onclick=()=>document.querySelector('[data-page="patients"]').click()});render();
